const express = require('express');
const app = express();

app.use(express.json());

function tokenize(input) {
  const tokens = [];
  let i = 0;

  while (i < input.length) {
    const ch = input[i];

    if (/\s/.test(ch)) {
      i += 1;
      continue;
    }

    const two = input.slice(i, i + 2);
    if (['&&', '||', '==', '!=', '>=', '<=', '===', '!=='].includes(input.slice(i, i + 3))) {
      tokens.push({ type: 'op', value: input.slice(i, i + 3) });
      i += 3;
      continue;
    }
    if (['&&', '||', '==', '!=', '>=', '<='].includes(two)) {
      tokens.push({ type: 'op', value: two });
      i += 2;
      continue;
    }
    if ('()[]+-*/%!<>,.'.includes(ch)) {
      tokens.push({ type: 'op', value: ch });
      i += 1;
      continue;
    }

    if (ch === '"' || ch === "'") {
      const quote = ch;
      let value = '';
      i += 1;
      while (i < input.length && input[i] !== quote) {
        if (input[i] === '\\') {
          i += 1;
          if (i >= input.length) throw new Error('Unterminated string literal');
          const escapes = { n: '\n', r: '\r', t: '\t', '\\': '\\', '"': '"', "'": "'" };
          value += escapes[input[i]] ?? input[i];
        } else {
          value += input[i];
        }
        i += 1;
      }
      if (input[i] !== quote) throw new Error('Unterminated string literal');
      i += 1;
      tokens.push({ type: 'literal', value });
      continue;
    }

    if (/\d/.test(ch)) {
      let num = ch;
      i += 1;
      while (i < input.length && /[\d.]/.test(input[i])) {
        num += input[i];
        i += 1;
      }
      const value = Number(num);
      if (Number.isNaN(value)) throw new Error('Invalid number literal');
      tokens.push({ type: 'literal', value });
      continue;
    }

    if (/[A-Za-z_$]/.test(ch)) {
      let ident = ch;
      i += 1;
      while (i < input.length && /[A-Za-z0-9_$]/.test(input[i])) {
        ident += input[i];
        i += 1;
      }
      if (ident === 'true') tokens.push({ type: 'literal', value: true });
      else if (ident === 'false') tokens.push({ type: 'literal', value: false });
      else if (ident === 'null') tokens.push({ type: 'literal', value: null });
      else if (ident === 'undefined') tokens.push({ type: 'literal', value: undefined });
      else tokens.push({ type: 'identifier', value: ident });
      continue;
    }

    throw new Error(`Unexpected character: ${ch}`);
  }

  return tokens;
}

function safeGet(target, key) {
  if (target == null) return undefined;
  if (['__proto__', 'prototype', 'constructor'].includes(String(key))) return undefined;
  return target[key];
}

function evaluateRuleExpression(expression, context) {
  const tokens = tokenize(expression);
  let pos = 0;

  function peek(value) {
    const token = tokens[pos];
    if (!token) return false;
    return value == null ? token : token.value === value;
  }

  function consume(value) {
    if (!peek(value)) return null;
    return tokens[pos++];
  }

  function expect(value) {
    const token = consume(value);
    if (!token) throw new Error(`Expected ${value}`);
    return token;
  }

  function parsePrimary() {
    const token = tokens[pos++];
    if (!token) throw new Error('Unexpected end of expression');

    let value;
    if (token.type === 'literal') {
      value = token.value;
    } else if (token.type === 'identifier') {
      if (token.value !== 'ctx') throw new Error(`Unknown identifier: ${token.value}`);
      value = context;
    } else if (token.value === '(') {
      value = parseOr();
      expect(')');
    } else {
      throw new Error(`Unexpected token: ${token.value}`);
    }

    while (peek('.') || peek('[')) {
      if (consume('.')) {
        const prop = tokens[pos++];
        if (!prop || prop.type !== 'identifier') throw new Error('Expected property name');
        value = safeGet(value, prop.value);
      } else if (consume('[')) {
        const prop = parseOr();
        expect(']');
        value = safeGet(value, prop);
      }
    }

    return value;
  }

  function parseUnary() {
    if (consume('!')) return !parseUnary();
    if (consume('-')) return -parseUnary();
    if (consume('+')) return +parseUnary();
    return parsePrimary();
  }

  function parseMultiplicative() {
    let left = parseUnary();
    while (peek('*') || peek('/') || peek('%')) {
      const op = tokens[pos++].value;
      const right = parseUnary();
      if (op === '*') left *= right;
      else if (op === '/') left /= right;
      else left %= right;
    }
    return left;
  }

  function parseAdditive() {
    let left = parseMultiplicative();
    while (peek('+') || peek('-')) {
      const op = tokens[pos++].value;
      const right = parseMultiplicative();
      if (op === '+') left += right;
      else left -= right;
    }
    return left;
  }

  function parseRelational() {
    let left = parseAdditive();
    while (peek('>') || peek('<') || peek('>=') || peek('<=')) {
      const op = tokens[pos++].value;
      const right = parseAdditive();
      if (op === '>') left = left > right;
      else if (op === '<') left = left < right;
      else if (op === '>=') left = left >= right;
      else left = left <= right;
    }
    return left;
  }

  function parseEquality() {
    let left = parseRelational();
    while (peek('==') || peek('!=') || peek('===') || peek('!==')) {
      const op = tokens[pos++].value;
      const right = parseRelational();
      if (op === '==') left = left == right; // eslint-disable-line eqeqeq
      else if (op === '!=') left = left != right; // eslint-disable-line eqeqeq
      else if (op === '===') left = left === right;
      else left = left !== right;
    }
    return left;
  }

  function parseAnd() {
    let left = parseEquality();
    while (consume('&&')) {
      left = parseEquality() && left;
    }
    return left;
  }

  function parseOr() {
    let left = parseAnd();
    while (consume('||')) {
      left = parseAnd() || left;
    }
    return left;
  }

  const result = parseOr();
  if (pos !== tokens.length) throw new Error(`Unexpected token: ${tokens[pos].value}`);
  return result;
}

